<template>
  <div class="candy-rain-container">
    <div
        v-for="candy in candyList"
        :key="candy.id"
        class="candy-item"
        :style="{
        left: candy.left + '%',
        animationDuration: candy.duration + 's',
        animationDelay: candy.delay + 's',
        transform: `rotate(${candy.rotateStart}deg)`,
        '--rotate-end': candy.rotateEnd + 'deg',
        fontSize: candy.size + 'px'
      }"
    >
      <img :src="require(`@/assets/images/candies/${candy.emoji}`)" alt="">
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import { eventBus, EVENT_CANDY_RAIN } from '@/utils/eventBus'

// 糖果 emoji 池（可自行扩展）
// const CANDY_EMOJIS = ['🍬', '🍭', '🍫', '🎃', '👻', '🦇', '🕸️', '🍩', '🧁']
const candy_array = [
    '01.png',
    '02.png',
    '03.png',
    '04.png',
    '05.png',
    '06.png',
    '07.png',
    '08.png',
    '09.png',
    '10.png',
    '11.png',
    '12.png',
    '13.png'
]
// 每次下落的糖果数量（固定）
const CANDY_COUNT = 12

// 下落时长范围（秒）
const DURATION_MIN = 2.5
const DURATION_MAX = 4.5

// 旋转角度范围
const ROTATE_RANGE = 720

// 字号范围
const SIZE_MIN = 24
const SIZE_MAX = 40

const candyList = ref([])
let idSeed = 0

// 生成一轮糖果雨
const createCandyRain = () => {
  const newCandies = []

  for (let i = 0; i < CANDY_COUNT; i++) {
    const duration = DURATION_MIN + Math.random() * (DURATION_MAX - DURATION_MIN)
    const id = ++idSeed

    newCandies.push({
      id,
      emoji: candy_array[Math.floor(Math.random() * candy_array.length)],
      // 水平均匀分布 + 微小随机偏移
      left: ((i + 0.5) / CANDY_COUNT) * 100 + (Math.random() * 4 - 2),
      duration,
      delay: Math.random() * 0.3,
      rotateStart: Math.random() * 360,
      rotateEnd: Math.random() * ROTATE_RANGE - ROTATE_RANGE / 2,
      size: SIZE_MIN + Math.random() * (SIZE_MAX - SIZE_MIN)
    })

    // 动画结束后自动移除
    setTimeout(() => {
      candyList.value = candyList.value.filter(c => c.id !== id)
    }, (duration + 0.3) * 1000)
  }

  candyList.value.push(...newCandies)
}

onMounted(() => {
  eventBus.on(EVENT_CANDY_RAIN, createCandyRain)
})

onUnmounted(() => {
  eventBus.off(EVENT_CANDY_RAIN, createCandyRain)
})
</script>

<style lang="scss" scoped>
.candy-rain-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  pointer-events: none;
  overflow: hidden;
  z-index: 9999;
}

.candy-item {
  position: absolute;
  top: -60px;
  user-select: none;
  animation-name: candyFall;
  animation-timing-function: ease-in;
  animation-fill-mode: forwards;
  will-change: transform, top;
  img{
    width: 48px;
  }
}

@keyframes candyFall {
  0% {
    top: -60px;
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  100% {
    top: 110vh;
    opacity: 0.8;
    transform: rotate(var(--rotate-end));
  }
}
</style>
