          name: this.$t('message.potion_5'),
        },
      ],
      chosen: "",
      blinkInterval: undefined,
      blinkInterval1: undefined,
      blinking: false
    };
  },
  methods: {
    toBack() {
      console.log("trigger");
      // this.$chosen = null;
      // this.$isChosen = false;
      this.$router.replace("/potion");
    },
    openAbout(){
      this.$refs.popup.doOpen();
    },
    openProg(){
      this.$refs.prog.doOpen();
    },
    doOpenSound(){
      this.$emit('openSettings', false)
    },
    openCandy(){
      this.$refs.candy.doOpen(this.chosen);
    },
    updateCount(chosen){
      let date = new Date();
      let timestamp = date.getTime();
      let select_sql = `update halloween2026_keys set key_values = key_values + 1 where key_name = 'potion${parseInt(chosen) + 1}_used'`;
      let sql1 = `insert into halloween_2026_log (time_stamp, key_name) values (${timestamp}, 'potion${parseInt(this.chosen) + 1}_used')`
      request.post('updateInfo.jsp', { "sqlstring": [select_sql, sql1] },
          { noVerify: true, noAuth: true }).then( res1 => {
        if (res1.msg && res1.msg.indexOf('出错') < 0){
        }
        else{
          this.$message.error(this.$t('message.server_error'))
        }
      }).catch(err => {
        this.$message.error(this.$t('message.server_error'));
        this.submitting = false;
      });

    },
  },
  created() {
    this.chosen = sessionStorage.getItem("chosen");
    console.log(this.chosen);

    this.$forceUpdate();
    this.updateCount(this.chosen);
    this.blinkInterval = setInterval(() => {
      this.blinking = true;
      setTimeout(() => this.blinking = false, 100)
    }, 3000)
    this.blinkInterval1 = setInterval(() => {
      this.blinking = true;
      setTimeout(() => this.blinking = false, 200)
    }, 5000)
    setTimeout(() => {
      document.getElementById('cover').style.opacity = 0;
    }, 1000);
    setTimeout(() => {
      document.getElementById('cover').style.display = 'none';
    }, 3500);


  },
  // mounted() {
  //   this.openCandy()
  // },
  beforeDestroy() {
    clearInterval(this.blinkInterval);
    clearInterval(this.blinkInterval1)
  }
};
</script>

