<script>
import request from "@/utils/request";
import {eventBus, EVENT_CANDY_RAIN} from "@/utils/eventBus";

export default {
  data(){
    return{
      show: false,
      osInfo: {},
      chosen: '',
      remaining_times: 0,
      last_time: '',
      submitting: false
    }
  },
  methods: {
    getTimes(){
      let date = new Date();
      let currDate = `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`
      let prevDate = localStorage.getItem('prevDate');
      if (!prevDate || currDate != prevDate){
        this.remaining_times = 10;
        localStorage.setItem('remainingTimes', this.remaining_times);
      }
      else{
        this.remaining_times = parseInt(localStorage.getItem('remainingTimes') || '10') ;
      }
      localStorage.setItem('prevDate', currDate)
    },
    handleClose() {
      this.show = false
    },
    doOpen(info){
      this.chosen = info;
      this.getTimes();
      this.show = true
    },
    giveCandy(){
      if (this.remaining_times === 0){
        return false;
      }
      console.log(this.chosen)
      let date = new Date();
      let timestamp = date.getTime();
      let sql = `update halloween2026_keys set key_values = key_values + 1 where key_name = 'potion${parseInt(this.chosen) + 1}_candies;'`
      let sql1 = `insert into halloween_2026_log (time_stamp, key_name) values (${timestamp}, 'potion${parseInt(this.chosen) + 1}_candies')`
      console.log(sql)
      this.submitting = true;
      try{
        request.post('updateInfo.jsp', { "sqlstring": [sql, sql1] },
            { noVerify: true, noAuth: true }).then(res => {
          if (res.msg && res.msg.indexOf('出错') < 0){
            this.$message.success(this.$t('message.candy_receive'));
            this.remaining_times = this.remaining_times - 1;
            localStorage.setItem('remainingTimes', this.remaining_times)
            eventBus.emit(EVENT_CANDY_RAIN)
          }
          else{
            this.$message.error(this.$t('message.server_error'))
          }
          this.submitting = false;
        }).catch(err => {
          this.$message.error(this.$t('message.server_error'));
          this.submitting = false;
        })
      }
      catch(err){
        this.$message.error(this.$t('message.server_error'));
        this.submitting = false;
      }

    }
  },
}
</script>

<template>
<el-dialog :visible="show" :beforeClose="handleClose" :modal="false">
  <div class="candy_outer">
    <p>⬇ {{$t('message.candy_1')}} ⬇</p>
    <button class="candy_btn" :class="submitting || remaining_times === 0? 'disabled_btn' : ''" @click="giveCandy" :disabled="submitting">
      {{submitting? $t('message.candy_2_wait') : `★${$t('message.candy_2')}★`}}
    </button>
    <p v-if="remaining_times > 0">{{$t('message.candy_3_before')}}{{remaining_times}}{{$t('message.candy_3_after')}}</p>
    <p v-else>{{$t('message.candy_3_out')}}</p>
  </div>
</el-dialog>
</template>
<style>

</style>
<style scoped lang="scss">
.el-dialog__wrapper{
  width: 100%;
  position: absolute;
  background: transparent !important;
}

:deep(.el-dialog){
  position: absolute;
  bottom: 0;
  margin: 0;
  width: 100% !important;
  border-radius: 48px 48px 0 0;
  box-shadow: 0 0 12px black;

}
:deep(.el-dialog__header){
  display: none;
}
.candy_outer{
  text-align: center;

  p{
    font-size: 16px;
  }
}
.candy_btn{
  width: 100%;
  height: 64px;
  border-radius: 64px;
  margin: 8px 0;
  font-family: "Cherry Bomb One", sans-serif;
  font-size: 24px;
  background-color: #ab47bc;
  color: white;
  box-shadow: 0 0 12px white;
  border: none;
  transition: 300ms;
  &:active{
    background-color: #8a0194;
  }
  &.disabled_btn{
    opacity: 0.5;
  }
}
</style>
